    if (message.method === "_nexus/receipt/get" && message.kind === "request") return this.getReceipt(message.id, message.params);
    if (message.kind === "request") this.replyError(message.id, { code: ACP_ERROR.METHOD_NOT_FOUND, message: `method not found: ${message.method}` });
  }

  private canonical(cwd: string): string | undefined {
    const result = canonicalCwd(cwd, {
      realpath: this.options.realpath ?? ((value) => fs.realpathSync(value)),
      isDirectory: this.options.isDirectory ?? ((value) => fs.statSync(value).isDirectory()),
    });
    return result.ok ? result.value : undefined;
  }

  private workspaceBase(cwd: string): PinnedBase | { error: string } {
    const pinned = this.workspaceBases.get(cwd);
    if (pinned) return pinned;
    if (this.workspaceBases.size >= ACP_MAX_PINNED_WORKSPACES) {
      return { error: `this nexus acp process has already pinned a verification base for ${ACP_MAX_PINNED_WORKSPACES} workspaces and pins no more; restart nexus acp to verify this workspace` };
    }
    const base = pinBase(cwd);
    this.workspaceBases.set(cwd, base);
    return base;
  }

    if (!receipt || receipt.session_id !== parsed.value.sessionId) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "receipt is not available on this connection" }); return; }
    this.send(resultResponse(id, receipt));
  }

  private hasVerificationOverlap(cwd: string): boolean {
    return [...this.sessions.values()].some((session) => session.pendingVerify && this.workspacesOverlap(cwd, session.cwd));
  }

  private hasPromptOverlap(cwd: string): boolean {
    return [...this.sessions.values()].some((session) => (session.pendingPrompt || session.stopping) && this.workspacesOverlap(cwd, session.cwd));
  }

  private workspacesOverlap(left: string, right: string): boolean {
    const within = (parent: string, child: string) => {
      const relative = path.relative(parent, child);
      return relative === "" || (!path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`));
    };
    return within(left, right) || within(right, left);
  }

  private async verify(id: AcpId, params: unknown): Promise<void> {
